{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, compared as exact strings.
 *
 * Ties are broken so that matches come as early as possible: walking both
 * documents from the start, a match is taken whenever the two current lines
 * are equal, and otherwise the side whose remaining subsequence is at least as
 * long as the other's is advanced, preferring to advance the base on a tie.
 */

/**
 * Suffix LCS length table: table[i][j] is the length of the longest common
 * subsequence of base.slice(i) and side.slice(j).
 */
function suffixTable(base, side) {
  const n = base.length
  const m = side.length
  const table = new Array(n + 1)
  for (let i = 0; i <= n; i += 1) table[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  return table
}

/**
 * The matched pairs [baseIndex, sideIndex] of the chosen subsequence.
 */
export function lcsMatches(base, side) {
  const table = suffixTable(base, side)
  const matches = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * The stretches the subsequence does not cover, each a run of base lines
 * replaced by a run of that side's lines. Ends are exclusive.
 */
export function diffChanges(base, side) {
  const changes = []
  let baseAt = 0
  let sideAt = 0
  for (const [i, j] of lcsMatches(base, side)) {
    if (i > baseAt || j > sideAt) {
      changes.push({ baseStart: baseAt, baseEnd: i, sideStart: sideAt, sideEnd: j })
    }
    baseAt = i + 1
    sideAt = j + 1
  }
  if (baseAt < base.length || sideAt < side.length) {
    changes.push({ baseStart: baseAt, baseEnd: base.length, sideStart: sideAt, sideEnd: side.length })
  }
  return changes
}
"}

