{"file_path":"src/diff3.js","content":"/**
 * The three-way merge itself: gathering both sides' changes against the base
 * into regions and resolving each region.
 */

import { diffChanges } from './lcs.js'

function equalLines(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * One side's lines for a region: the smallest start of its own changes moved
 * back by however far the region begins before those changes, to the largest
 * end of its own changes moved forward by however far the region ends after
 * them. A side that did not change anything in the region keeps the base.
 */
function sideLines(changes, side, base, regionStart, regionEnd) {
  if (changes.length === 0) return base.slice(regionStart, regionEnd)
  let baseStart = Infinity
  let baseEnd = -Infinity
  let start = Infinity
  let end = -Infinity
  for (const change of changes) {
    baseStart = Math.min(baseStart, change.baseStart)
    baseEnd = Math.max(baseEnd, change.baseEnd)
    start = Math.min(start, change.sideStart)
    end = Math.max(end, change.sideEnd)
  }
  return side.slice(start - (baseStart - regionStart), end + (regionEnd - baseEnd))
}

/**
 * The regions of the merge, in order. A stable region carries the base lines
 * it keeps; every other region carries all three sides' lines.
 */
export function mergeRegions(mine, base, theirs) {
  const changes = []
  for (const change of diffChanges(base, mine)) changes.push({ ...change, from: 'mine' })
  for (const change of diffChanges(base, theirs)) changes.push({ ...change, from: 'theirs' })
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.from === b.from) return 0
    return a.from === 'mine' ? -1 : 1
  })

  const regions = []
  let at = 0
  let index = 0
  while (index < changes.length) {
    const group = [changes[index]]
    let start = changes[index].baseStart
    let end = changes[index].baseEnd
    index += 1
    while (index < changes.length && changes[index].baseStart <= end) {
      end = Math.max(end, changes[index].baseEnd)
      group.push(changes[index])
      index += 1
    }
    if (start > at) regions.push({ kind: 'stable', lines: base.slice(at, start) })
    const mineLines = sideLines(group.filter(c => c.from === 'mine'), mine, base, start, end)
    const theirsLines = sideLines(group.filter(c => c.from === 'theirs'), theirs, base, start, end)
    const baseLines = base.slice(start, end)
    regions.push(resolve(mineLines, baseLines, theirsLines))
    at = end
  }
  if (at < base.length) regions.push({ kind: 'stable', lines: base.slice(at) })
  return regions
}

function resolve(mine, base, theirs) {
  if (equalLines(mine, theirs)) return { kind: 'both', mine, base, theirs, lines: mine }
  if (equalLines(mine, base)) return { kind: 'theirs', mine, base, theirs, lines: theirs }
  if (equalLines(theirs, base)) return { kind: 'mine', mine, base, theirs, lines: mine }
  return { kind: 'conflict', mine, base, theirs, lines: null }
}
