{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { mergeRegions } from './diff3.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** The three documents the input holds, or a failure. */
function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  return parts
}

function renderMerge(regions, withBase) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push('<<<<<<< mine', ...region.mine)
      if (withBase) out.push('||||||| base', ...region.base)
      out.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { out, conflicted }
}

function renderRegions(regions) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { out, conflicted }
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || !MODES.includes(argv[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = argv[0]

  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  const [mine, base, theirs] = parseInput(text)
  const regions = mergeRegions(mine, base, theirs)

  const { out, conflicted } = mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')
  process.stdout.write(out.map(line => `${line}\n`).join(''))
  process.exit(conflicted ? 1 : 0)
}

main()
"}

